export const meta = {
  "slug": "lucide-phone-call",
  "family": "lucide",
  "name": "phone-call",
  "category": "Communication",
  "motion": "shake",
  "component": "createLucidePhoneCallIcon"
};

export function createLucidePhoneCallIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
